export function interpolate(value, params = {}) {
  if (typeof value !== 'string' || !params || typeof params !== 'object') return value
  return value.replace(/\{(\w+)\}/g, (placeholder, key) => Object.prototype.hasOwnProperty.call(params, key) ? String(params[key]) : placeholder)
}

export function translate(value, locale = 'zh', params = undefined) {
  if (locale === 'zh' || typeof value !== 'string') return interpolate(value, params)
  const translation = packs[locale]?.[value]
  // An absent, empty, or historical placeholder translation must remain
  // readable Chinese instead of being rendered as a misleading fallback.
  if (typeof translation === 'string' && translation.trim() && translation !== 'Localized information') return interpolate(translation, params)

  // Existing pages compose this toast from stable labels. Keep their original
  // keys untouched while translating the visible status after a locale change.
  const themeChange = value.match(/^已切换为(.+)背景$/)
  if (themeChange) return `${translate('已切换为', locale)}${translate(themeChange[1], locale)}${translate('背景', locale)}`
  return interpolate(value, params)
}

export function sourceValue(value, locale = 'zh') {
  if (locale === 'zh' || typeof value !== 'string') return value
  const matches = Object.entries(packs[locale] || {}).filter(([, translated]) => translated === value)
  return matches.length === 1 ? matches[0][0] : value
}

export function localizePage(value, locale = 'zh') {
  if (Array.isArray(value)) return value.map((item) => localizePage(item, locale))
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localizePage(item, locale)]))
  return translate(value, locale)
}

export const supportedLocales = Object.freeze(['zh', 'en', 'ja', 'ru', 'de'])

// Terms whose Chinese glyph is also the correct Japanese display form.  Keep
// this registry explicit so untranslated UI text is never silently ignored.
export const retainedSourceTerms = Object.freeze({ ja: Object.freeze(['第']) })

export function untranslatedTerms(values, locale = 'zh') {
  if (!Array.isArray(values) || locale === 'zh') return []
  const retained = retainedSourceTerms[locale] || []
  return values.filter((value) => typeof value === 'string' && translate(value, locale) === value && !retained.includes(value))
}
